"use client"
import { useRef, useState } from "react"

const CLIPS: Record<string, string> = {"A": "data:audio/mpeg;base64,", "B": "data:audio/mpeg;base64,", "C": "data:audio/mpeg;base64,"}
const LABELS: Record<string, string> = {"A": "Voice A (female, Ava)", "B": "Voice B (male, Brian)", "C": "Voice C (female, Emma)"}

export default function VoiceTest() {
  const refs = useRef<Record<string, HTMLAudioElement | null>>({})
  const [msg, setMsg] = useState("Tap a button. Ring switch on, volume up.")
  const play = (k: string) => {
    Object.values(refs.current).forEach((a) => { if (a) { a.pause(); a.currentTime = 0 } })
    const a = refs.current[k]
    if (!a) return
    a.play().then(() => setMsg("Playing " + LABELS[k])).catch((e) => setMsg("Blocked: " + String(e)))
  }
  return (
    <main style={{ minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, padding: 24, background: "#0f172a", color: "#fff", fontFamily: "sans-serif", textAlign: "center" }}>
      <h1 style={{ fontSize: 24 }}>Hamo voice test</h1>
      {Object.keys(CLIPS).map((k) => (
        <div key={k}>
          <button onClick={() => play(k)} style={{ fontSize: 20, padding: "14px 28px", borderRadius: 12, background: "#10b981", color: "#04130d", border: 0, minWidth: 260 }}>Play {LABELS[k]}</button>
          <audio ref={(el) => { refs.current[k] = el }} src={CLIPS[k]} preload="auto" playsInline />
        </div>
      ))}
      <p style={{ maxWidth: 320 }}>{msg}</p>
    </main>
  )
}
